def solution(land):
    rows = len(land)
    cols = len(land[0])

    dp = [[0] * cols for _ in range(rows)]

    for c in range(cols):
        dp[0][c] = land[0][c]

    for r in range(1, rows):
        for c in range(cols):
            max_above = 0
            if c > 0:
                max_above = max(max_above, dp[r-1][c-1])
            if c < cols - 1:
                max_above = max(max_above, dp[r-1][c+1])
            dp[r][c] = land[r][c] + max_above

    return max(max(row) for row in dp) if dp else 0

